require_once __DIR__.'/../config/bootstrap.php';$token=$_GET['token']??'';$ok=false;$message='Lien invalide ou expiré.';
if(is_string($token)&&preg_match('/^[a-f0-9]{64}$/',$token)){$q=$pdo->prepare('SELECT ev.id verification_id,ev.user_id,u.account_type FROM email_verifications ev JOIN users u ON u.id=ev.user_id WHERE ev.token_hash=? AND ev.used_at IS NULL AND ev.expires_at>NOW() LIMIT 1');$q->execute([hash('sha256',$token)]);$r=$q->fetch();if($r){$pdo->beginTransaction();$pdo->prepare('UPDATE email_verifications SET used_at=NOW() WHERE id=?')->execute([$r['verification_id']]);if($r['account_type']==='client'){$pdo->prepare("UPDATE users SET is_email_verified=1,account_status='active' WHERE id=?")->execute([$r['user_id']]);$message='E-mail confirmé. Votre compte client est activé.';}else{$pdo->prepare('UPDATE users SET is_email_verified=1 WHERE id=?')->execute([$r['user_id']]);$message='E-mail confirmé. Votre profil artisan attend la validation de FIXI.';}$pdo->commit();$ok=true;}}
$pageTitle='Vérification e-mail';require __DIR__.'/../includes/header.php';?><main class="container py-5"><div class="auth-card mx-auto text-center"><div class="display-5"><?=$ok?'✓':'!'?></div><h1 class="h3 mt-3">Vérification e-mail</h1><p class="text-secondary"><?=e($message)?></p><a class="btn btn-fixi" href="login.php">Connexion</a></div></main><?php require __DIR__.'/../includes/footer.php';?>
